Cho hai điểm ${L}$, ${M}$ nằm trên đường tròn $({O'})$ và cho điểm ${G}$ nằm trên cung lớn $\wideparen{LM}$. Biết rằng $\widehat{O'LG} = 32^{\circ}$, $\widehat{O'MG} = 38^{\circ}$. Xét tính đúng sai của các khẳng định sau.

\choiceTF
{ \True $\widehat{GLM} = 52^{\circ}$ }
   {  $\widehat{GML}= 68^{\circ}$ }
     { \True $\widehat{LGM}=70^{\circ}$  }
    { $\widehat{O'LM}=40^{\circ} $   }
}{
\begin{tikzpicture}[>=stealth,line join=round,line cap=round,font=\footnotesize,scale=1]
                \path 
                (0,0) coordinate (O)
                ($(O) + (100:2)$) coordinate (A)
                ($(O) + (-15:2)$) coordinate (B)
                ($(O) + (-165:2)$) coordinate (C)
                ;
                \draw (O) circle (2cm);
                \draw (C)--(B)--(A)--(C)--(A)--(O)--(B) (O)--(C);
                     \node[above left] at (A) {$G$};
      \node[above right] at (B) {$L$};
       \node[above left] at (C) {$M$};
        \node[above left] at (O) {$O'$};
                \fill[black] (B) +(150:7.3mm) node[scale=0.8]{$32^\circ$};
                \fill[black] (C) +(30:5.5mm) node[scale=0.8]{$38^\circ$};
            \end{tikzpicture}
}
\loigiai{
a) Khẳng định đã cho là khẳng định đúng.\\
Vì tam giác ${O'GL}$ cân tại ${O'}$ nên\\
$ \widehat{GO'L} = 180^{\circ} - \widehat{O'GL} - \widehat{O'LG} = 180^{\circ} - 2\widehat{O'LG} = 116^{\circ} $\\
Vì tam giác ${O'GM}$ cân tại ${O'}$ nên\\
$ \widehat{GO'M} = 180^{\circ} - \widehat{O'GM} - \widehat{O'MG} = 180^{\circ} - 2\widehat{O'MG} = 104^{\circ} $\\
Xét trong đường tròn $({O'})$, ta có\\
Góc nội tiếp $\widehat{GLM}$ và góc ở tâm $\widehat{GO'M}$ cùng chắn cung nhỏ $\wideparen{GM}$ nên\\
$\widehat{GLM} = \dfrac{1}{2}\widehat{GO'M} = 52^{\circ}$\\
Góc nội tiếp $\widehat{GML}$ và góc ở tâm $\widehat{GO'L}$ cùng chắn cung nhỏ $\wideparen{GL}$ nên\\
$\widehat{GML} = \dfrac{1}{2}\widehat{GO'L} = 58^{\circ}$\\
$\widehat{LGM}=180^{\circ}-\widehat{GML}-\widehat{GLM} =70^{\circ}$\\
b) Khẳng định đã cho là khẳng định sai.\\
$\widehat{GML}= 58^{\circ}$\\
c) Khẳng định đã cho là khẳng định đúng.\\
$\widehat{LGM}=70^{\circ}$\\
d) Khẳng định đã cho là khẳng định sai.\\
$\widehat{O'LM}=   \widehat{GLM} - \widehat{O'LG}   =20^{\circ} $
}\end{ex}

