Cho hai điểm ${I}$, ${K}$ nằm trên đường tròn $({O'})$ và cho điểm ${H}$ nằm trên cung lớn $\wideparen{IK}$. Biết rằng $\widehat{O'IH} = 25^{\circ}$, $\widehat{O'KH} = 29^{\circ}$. Xét tính đúng sai của các khẳng định sau.

\choiceTF
{ \True $\widehat{HIK} = 61^{\circ}$ }
   {  $\widehat{HKI}= 75^{\circ}$ }
     {  $\widehat{IHK}=64^{\circ}$ }
    { \True $\widehat{O'IK}=36^{\circ} $  }
}{
\begin{tikzpicture}[>=stealth,line join=round,line cap=round,font=\footnotesize,scale=1]
                \path 
                (0,0) coordinate (O)
                ($(O) + (100:2)$) coordinate (A)
                ($(O) + (-15:2)$) coordinate (B)
                ($(O) + (-165:2)$) coordinate (C)
                ;
                \draw (O) circle (2cm);
                \draw (C)--(B)--(A)--(C)--(A)--(O)--(B) (O)--(C);
                     \node[above left] at (A) {$H$};
      \node[above right] at (B) {$I$};
       \node[above left] at (C) {$K$};
        \node[above left] at (O) {$O'$};
                \fill[black] (B) +(150:7.3mm) node[scale=0.8]{$25^\circ$};
                \fill[black] (C) +(30:5.5mm) node[scale=0.8]{$29^\circ$};
            \end{tikzpicture}
}
\loigiai{
a) Khẳng định đã cho là khẳng định đúng.\\
Vì tam giác ${O'HI}$ cân tại ${O'}$ nên\\
$ \widehat{HO'I} = 180^{\circ} - \widehat{O'HI} - \widehat{O'IH} = 180^{\circ} - 2\widehat{O'IH} = 130^{\circ} $\\
Vì tam giác ${O'HK}$ cân tại ${O'}$ nên\\
$ \widehat{HO'K} = 180^{\circ} - \widehat{O'HK} - \widehat{O'KH} = 180^{\circ} - 2\widehat{O'KH} = 122^{\circ} $\\
Xét trong đường tròn $({O'})$, ta có\\
Góc nội tiếp $\widehat{HIK}$ và góc ở tâm $\widehat{HO'K}$ cùng chắn cung nhỏ $\wideparen{HK}$ nên\\
$\widehat{HIK} = \dfrac{1}{2}\widehat{HO'K} = 61^{\circ}$\\
Góc nội tiếp $\widehat{HKI}$ và góc ở tâm $\widehat{HO'I}$ cùng chắn cung nhỏ $\wideparen{HI}$ nên\\
$\widehat{HKI} = \dfrac{1}{2}\widehat{HO'I} = 65^{\circ}$\\
$\widehat{IHK}=180^{\circ}-\widehat{HKI}-\widehat{HIK} =54^{\circ}$\\
b) Khẳng định đã cho là khẳng định sai.\\
$\widehat{HKI}= 65^{\circ}$\\
c) Khẳng định đã cho là khẳng định sai.\\
$\widehat{IHK}=54^{\circ}$\\
d) Khẳng định đã cho là khẳng định đúng.\\
$\widehat{O'IK}=   \widehat{HIK} - \widehat{O'IH}   =36^{\circ} $
}\end{ex}

